@@ -1,7 +1,16 @@
 import type { Provenance } from "./grade.ts";

-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
-  const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+export interface CommitIdentity {
+  author: string;
+  committer: string;
+}
+
+export const provenanceOf = (commit: CommitIdentity): Provenance => {
+  if (commit.author === commit.committer) {
+    return "authored";
+  }
+  if (commit.author && commit.committer) {
+    return "inherited";
+  }
   return "unknown";
 };
